INSERT INTO `product_detail` VALUES (1, 1, 'Apple MacBook Air 13 英寸 M3 轻薄本主打轻薄机身、长续航和高性能芯片，适合大学生学习、办公人群移动办公、内容创作者轻度剪辑和日常生产力场景。机身便携，屏幕显示细腻，适合经常携带电脑上课、出差和会议的人群。', 'MacBook Air 主机、电源适配器、USB-C 充电线、快速入门资料。', '支持 7 天无理由退换，整机按品牌官方政策享受质保服务，人为损坏和进液不在普通质保范围内。', '轻薄长续航笔记本，适合预算充足、重视便携和系统稳定性的学习办公用户。', '2026-06-26 14:00:00', '2026-06-26 14:00:00');
INSERT INTO `product_detail` VALUES (2, 2, '联想小新 Pro 14 酷睿版笔记本电脑定位高性价比全能本，适合编程学习、毕业设计、文档处理、网课和轻度创作。高分屏显示清晰，性能释放稳定，键盘手感适合长时间输入。', '笔记本电脑、电源适配器、保修卡、使用说明。', '支持 7 天无理由退换，主要部件按品牌官方政策质保，外观磨损和人为拆修不在普通质保范围内。', '高性价比编程学习笔记本，适合学生党、毕业设计和 Java/Vue 项目开发。', '2026-06-26 14:01:00', '2026-06-26 14:01:00');
INSERT INTO `product_detail` VALUES (3, 3, '华为 MateBook 14 全能办公本适合办公、学习、多设备协同和轻度创作。高分辨率屏幕适合阅读代码、文档和表格，多屏协同能力适合已经使用华为手机或平板的用户。', '笔记本电脑、电源适配器、数据线、用户指南。', '支持 7 天无理由退换，按品牌官方政策提供质保服务。', '适合华为生态用户和办公学习人群的全能轻薄本。', '2026-06-26 14:02:00', '2026-06-26 14:02:00');
INSERT INTO `product_detail` VALUES (4, 4, 'iPhone 16 Pro 256GB 智能手机面向旗舰手机用户，适合高频拍照、视频创作、移动办公和长期使用。系统流畅，影像能力强，适合重视稳定性和生态体验的用户。', '手机主机、USB-C 数据线、取卡针、资料卡。', '支持 7 天无理由退换，按品牌官方政策提供质保，屏幕碎裂、进液和私自维修不在普通质保范围内。', '旗舰影像手机，适合重视拍照、视频和生态体验的高预算用户。', '2026-06-26 14:03:00', '2026-06-26 14:03:00');
INSERT INTO `product_detail` VALUES (5, 5, '小米 15 Pro 512GB 智能手机兼顾旗舰性能、长续航和高性价比，适合游戏、拍照、日常高频使用和智能家居联动场景。大容量存储适合照片、视频和应用较多的用户。', '手机主机、充电器、数据线、保护壳、取卡针、说明书。', '支持 7 天无理由退换，按品牌官方政策提供质保服务。', '高性价比旗舰手机，适合关注性能、续航和大容量存储的用户。', '2026-06-26 14:04:00', '2026-06-26 14:04:00');
INSERT INTO `product_detail` VALUES (6, 6, 'Apple AirPods Pro 主动降噪耳机适合通勤、学习、运动和办公会议。主动降噪可以降低环境噪声，通透模式方便随时交流，佩戴体验适合长时间使用。', '耳机、充电盒、耳塞套、充电线、说明资料。', '支持 7 天无理由退换，耳机类商品需保持配件完整和外观完好。', '适合通勤学习和苹果生态用户的主动降噪耳机。', '2026-06-26 14:05:00', '2026-06-26 14:05:00');
INSERT INTO `product_detail` VALUES (7, 8, '戴森 V12 无线吸尘器适合家庭深度清洁、宠物毛发清理、地毯和缝隙清洁。轻量机身降低长时间使用负担，强劲吸力适合对清洁效果要求高的家庭。', '吸尘器主机、吸头组件、充电底座、电源适配器、说明书。', '支持 7 天无理由退换，滤芯和耗材按商品使用情况判断退换范围。', '高端清洁电器，适合重视家居清洁体验和吸力表现的用户。', '2026-06-26 14:06:00', '2026-06-26 14:06:00');
INSERT INTO `product_detail` VALUES (8, 17, 'Java 编程思想与项目实战套装适合计算机专业学生、转码学习者和准备毕业设计的用户。内容覆盖 Java 基础、Spring Boot 项目开发、前后端分离实践和常见业务模块设计。', '纸质图书套装、学习路线卡、配套资料说明。', '图书类商品支持非人为损坏退换，已明显阅读或折损会影响退换。', '适合 Java 后端入门、Spring Boot 项目实战和毕业设计准备的学习资料。', '2026-06-26 14:07:00', '2026-06-26 14:07:00');
