INSERT INTO `product_detail` VALUES (10, 9, '小米扫地机器人 Pro 支持激光导航自动规划清扫路径，扫拖一体设计可以同时完成吸尘和拖地，支持手机 App 设置清扫区域和禁区，适合有地板和瓷砖的家庭日常清洁。', '机器人主机、充电座、电源适配器、拖布组件、备用滤网和说明书。', '支持 7 天无理由退换，主机享受一年质保，滤网、拖布等耗材不在质保范围。', '自动规划路径的扫拖一体机器人，适合想省时省力做日常清洁的家庭用户。', '2026-06-26 14:05:00', '2026-06-26 14:05:00');
INSERT INTO `product_detail` VALUES (11, 10, '美的空气炸锅 5L 家用版采用大容量炸篮，支持多档温度和定时设置，无需大量食用油即可完成炸鸡、薯条、烤翅和烘焙，适合宿舍、单身公寓和三口之家使用。', '炸锅主机、5L 炸篮、隔油网、食谱手册和说明书。', '支持 7 天无理由退换，整机一年质保，炸篮涂层因使用磨损不在质保范围。', '大容量低油空气炸锅，适合追求少油烹饪和操作简单的家庭厨房。', '2026-06-26 14:05:00', '2026-06-26 14:05:00');
