INSERT INTO `product_detail` VALUES (17, 16, '智能筋膜枪专业放松版提供多档力度调节和多种按摩头，可以针对肩颈、腰背和腿部肌肉做放松，配备静音马达和便携收纳盒，适合运动后恢复和久坐人群缓解酸胀。', '筋膜枪主机、四种按摩头、充电器、收纳盒和说明书。', '支持 7 天无理由退换，主机一年质保，按摩头和电池属于易损件按品牌政策执行。', '多档位便携筋膜枪，适合运动后放松和久坐人群日常按摩。', '2026-06-26 14:05:00', '2026-06-26 14:05:00');
