INSERT INTO `after_sale_rule` VALUES (1, '七天无理由退货规则', 'RETURN', NULL, '用户收到商品后对商品不满意，且商品不影响二次销售', '签收后 7 天内，商品包装、配件、发票和赠品保持完整，数码激活类、贴身美妆类和定制类商品按商品详情页规则执行。', '用户在订单详情中提交退货说明，客服审核通过后寄回商品，仓库验收无误后按原支付路径退回余额。', '1-3 个工作日审核，仓库签收后 1-2 个工作日退款', '订单售后入口、在线客服', 1, 1, '2026-06-27 10:00:00', '2026-06-27 10:00:00');
INSERT INTO `after_sale_rule` VALUES (2, '数码商品质量问题换货规则', 'EXCHANGE', NULL, '手机、电脑、耳机等数码商品出现非人为质量问题', '商品在质保期内出现无法正常开机、屏幕异常、充电异常、按键失灵等问题，并经客服或品牌售后判断属于质量问题。', '用户提交问题描述和图片或视频凭证，客服确认后生成换货指引，仓库收到原商品并核验后寄出同款商品。', '1-3 个工作日审核，换货商品 3-5 个工作日寄出', '在线客服、品牌售后电话', 1, 2, '2026-06-27 10:01:00', '2026-06-27 10:01:00');
INSERT INTO `after_sale_rule` VALUES (3, '家电商品质保维修规则', 'WARRANTY', NULL, '家电商品在质保期内出现使用故障', '商品处于品牌质保期内，故障非进水、摔坏、私自拆修等人为原因导致，用户可提供订单记录和故障现象。', '客服登记问题后指引用户联系品牌售后或安排维修网点，维修进度由用户和售后网点确认。', '客服登记 1 个工作日内完成，维修时效以品牌售后为准', '在线客服、品牌售后网点', 1, 3, '2026-06-27 10:02:00', '2026-06-27 10:02:00');
INSERT INTO `after_sale_rule` VALUES (4, '订单取消退款规则', 'REFUND', NULL, '已支付但尚未发货的订单需要取消', '订单状态为已支付且未发货，用户或管理员可以取消订单。已发货订单需要走退货流程。', '系统取消订单后自动退回用户钱包余额，同时扣回管理员账户收入，并恢复对应商品库存。', '系统实时处理', '我的订单、后台订单管理', 1, 4, '2026-06-27 10:03:00', '2026-06-27 10:03:00');
INSERT INTO `after_sale_rule` VALUES (5, '物流异常处理规则', 'LOGISTICS', NULL, '商品长时间未更新物流、派送异常或签收异常', '订单已发货后物流超过 48 小时无更新，或出现派送失败、地址异常、签收异常等情况。', '用户联系在线客服提供订单编号，客服核实物流状态后协助催促快递、修改配送信息或登记补发处理。', '1 个工作日内反馈处理结果', '在线客服、物流客服', 1, 5, '2026-06-27 10:04:00', '2026-06-27 10:04:00');
